// @vitest-environment node
import path from 'node:path';
import ts from 'typescript';

// CI typechecks a clean checkout: next-env.d.ts and .next/ are generated by `next dev` /
// `next build`, are gitignored, and do not exist there. This compiles the folder with the
// real tsconfig minus those generated files, as CI sees it.
const root = path.resolve(__dirname, '..');

function programAsInCleanCheckout(configFile: string): ts.Program {
  const { config } = ts.readConfigFile(path.join(root, configFile), ts.sys.readFile);
  const parsed = ts.parseJsonConfigFileContent(config, ts.sys, root);
  const generated = (file: string) =>
    path.basename(file) === 'next-env.d.ts' || file.split(path.sep).includes('.next');
  return ts.createProgram({
    rootNames: parsed.fileNames.filter((file) => !generated(file)),
    options: { ...parsed.options, noEmit: true, incremental: false },
  });
}

describe('typecheck on a clean checkout', () => {
  it('[621-AC-01] resolves the types of static image imports without the generated next-env.d.ts', () => {
    const program = programAsInCleanCheckout('tsconfig.json');
    const unresolvedImages = program
      .getSourceFiles()
      .filter((file) => !file.fileName.includes('node_modules'))
      .flatMap((file) => program.getSemanticDiagnostics(file))
      .filter((d) => d.code === 2307)
      .map((d) => ts.flattenDiagnosticMessageText(d.messageText, '\n'))
      .filter((message) => /\.(svg|png|jpe?g|gif|webp|avif|ico|bmp)'/.test(message));

    expect(unresolvedImages).toEqual([]);
  }, 120_000);
});
